/* ------------------------------------------------------------------ *
 * 4. Derivation
 * ------------------------------------------------------------------ */

/** True when a multi-select answer array contains `value`. */
export function has(list, value) {
  return Array.isArray(list) && list.includes(value);
}

function any(list, values) {
  return values.some((v) => has(list, v));
}

/**
 * Organizational complexity: how many moving parts the analysis has to
 * hold together. Independent of whether the records are reachable.
 */
export function readStructure(a) {
  const signals = [];
  if (a.boundary === 'several_enterprises') signals.push('Several entities in one boundary');
  if (a.boundary === 'government_and_enterprises')
    signals.push('A government and its enterprises in one boundary');
  if (a.where === 'multi_site_one_state') signals.push('Several locations in one state');
  if (a.where === 'multi_state') signals.push('Activity in more than one state');
  if (has(a.activities, 'federal_contracting')) signals.push('Federal contracting');
  if (a.gaming_related_ops === 'together') signals.push('Gaming alongside related operations');
  if (a.intercompany === 'yes') signals.push('Transactions between the entities in scope');
  const sectorCount = (a.activities || []).filter(
    (v) => v !== 'not_sure' && v !== 'other',
  ).length;
  if (sectorCount >= 3) signals.push(`${sectorCount} kinds of activity`);

  const level = signals.length === 0 ? 'single' : signals.length <= 2 ? 'few' : 'several';
  const label =
    level === 'single'
      ? 'One operation, one place'
      : level === 'few'
        ? 'A few linked parts'
        : 'Several linked parts';
  return {
    level,
    label,
    signals,
    detail:
      level === 'single'
        ? 'Nothing here needs coordinating across entities or states.'
        : 'Each of these is a scope decision to settle, not a reason to wait.',
  };
}

/**
 * Data readiness: what can actually be reached. Deliberately separate from
 * structure, and never combined with it.
 */
export function readRecords(a) {
  const reachable = (a.available || []).filter((v) => v !== 'none_yet');
  const hasMoney = any(a.available, ['audited_financials', 'internal_financials', 'budget']);
  const hasLabor = any(a.available, ['payroll', 'roster']);
  const nothing = has(a.available, 'none_yet') || reachable.length === 0;

  const level = nothing ? 'unknown' : hasMoney && hasLabor ? 'ready' : 'partial';
  const label =
    level === 'ready'
      ? 'Enough in hand to start'
      : level === 'partial'
        ? 'Some records in hand'
        : 'Records still to locate';

  const notes = [];
  if (a.records_held === 'separate')
    notes.push('Records sit with separate entities or departments, so the first step is a list of who holds what.');
  if (a.records_held === 'mixed')
    notes.push('Some records are central and some are not, so name a holder for each gap.');
  if (a.records_held === 'not_sure')
    notes.push('Where the records live is itself one of the first things to establish.');
  if (!hasMoney && !nothing) notes.push('An operating measure in dollars is the one thing an analysis cannot start without.');
  if (!hasLabor && !nothing) notes.push('Payroll and headcount are what turn output into jobs and income.');

  return { level, label, reachable, notes };
}

/** The proposed boundary, in one sentence a coordinator can repeat. */
export function readScope(a) {
  const boundaryText = {
    one_enterprise: 'one enterprise',
    several_enterprises: 'a named set of enterprises',
    government: 'the government itself',
    government_and_enterprises: 'the government together with its enterprises',
    one_project: 'one project',
  }[a.boundary];

  const placeText = {
    one_site: 'in the one place the activity happens',
    multi_site_one_state: 'across the locations in one state',
    multi_state:
      a.multi_state_anchor === 'concentrated'
        ? 'starting with the state that holds most of the activity'
        : 'starting with one state, with the others following as their own analyses',
    not_sure: 'in a region to be settled on the call',
  }[a.where];

  if (!boundaryText) {
    return {
      settled: false,
      title: 'Start with a scoping conversation.',
      sentence:
        'The boundary is the first thing to settle. One conversation is usually enough to name it.',
      facts: [],
      bounds: [],
    };
  }

  const bounds = [
    'One reporting year, the most recent one with complete records.',
    'One region. More geographies run as their own analyses in the same series.',
  ];
  if (a.boundary === 'several_enterprises' || a.boundary === 'government_and_enterprises') {
    bounds.push('A named list of entities, agreed before the records are gathered.');
  }
  if (a.gaming_related_ops === 'gaming_only') {
    bounds.push('Gaming only. Lodging, food service and retail can join a later analysis.');
  }
  if (a.contracting_place === 'elsewhere' || a.contracting_place === 'mixed') {
    bounds.push('Only work performed inside the region is reported there.');
  }

  /* The facts a coordinator repeats, kept as fields rather than buried in
     the sentence, so the plan can lead with them. */
  const facts = [
    { k: 'Covers', v: boundaryText },
    {
      k: 'Where',
      v: {
        one_site: 'One location',
        multi_site_one_state: 'One state, several locations',
        multi_state:
          a.multi_state_anchor === 'concentrated'
            ? 'The state holding most of the activity, first'
            : 'One state first, the others as their own analyses',
        not_sure: 'To be settled on the call',
      }[a.where],
    },
    { k: 'Period', v: 'One reporting year' },
  ];
  if (a.goal && a.goal !== 'not_sure') {
    facts.push({
      k: 'Purpose',
      v: {
        current_operations: 'What current operations contribute',
        project: 'What one project or expansion would support',
        enterprises_and_government: 'Enterprises and government together',
      }[a.goal],
    });
  }

  return {
    settled: true,
    title: `Start with ${boundaryText}, for one year.`,
    sentence: `Start with ${boundaryText}, ${placeText}, for one reporting year.`,
    facts,
    bounds,
  };
}

/** What a first analysis on this scope can report, and what it cannot yet. */
export function readFirstOutput(a) {
  const can = [];
  const notYet = [];

  if (a.boundary) {
    can.push('Jobs, labor income, value added and economic output supported in the region.');
    can.push('Direct, indirect and induced effects reported separately.');
    can.push('Each figure traceable to the record it came from, with every assumption listed.');
  }
  if (a.boundary === 'government_and_enterprises' || a.boundary === 'government') {
    can.push('The government reported as its own account rather than folded into an industry.');
  }
  if (a.where === 'multi_state') {
    notYet.push(
      'A single combined figure across states. One analysis covers one region, so the states run as their own analyses.',
    );
  }
  if (a.gaming_separable === 'combined') {
    notYet.push(
      'Gaming reported separately from the operations bundled into the same figure. They are reported together, and the result says so.',
    );
  }
  if (a.contracting_subs === 'yes' || a.contracting_subs === 'not_sure') {
    notYet.push(
      'Subcontracted work attributed to the subcontractor rather than to your organization, until the pass-through share is known.',
    );
  }
  if (has(a.audience, 'funder')) {
    can.push('An export carrying the inputs, the assumptions and the data vintages behind the figure.');
  }
  notYet.push(
    'Observed local purchasing. Purchasing is estimated from regional trade data, and the estimate is stated as an assumption.',
  );
  return { can, notYet };
}

/**
 * The tailored checklist. Three categories, and which category a record
 * falls into depends on the scope, never on a universal ranking.
 * Returns records in a stable order within each tier.
 */
export function readChecklist(a) {
  /** @type {{id: string, tier: 'begin'|'refine'|'later', why?: string}[]} */
  const picks = [];
  const add = (id, tier, why) => picks.push({ id, tier, why });

  const governmentInScope =
    a.boundary === 'government' || a.boundary === 'government_and_enterprises';
  const enterprisesInScope =
    a.boundary === 'one_enterprise' ||
    a.boundary === 'several_enterprises' ||
    a.boundary === 'government_and_enterprises' ||
    a.boundary === 'one_project';

  if (enterprisesInScope) {
    add('financials', 'begin');
    add('payroll', 'begin');
    add('headcount', 'begin');
  }
  if (governmentInScope) {
    add('gov_financials', 'begin');
    add(
      'gov_funding',
      a.boundary === 'government' ? 'begin' : 'refine',
      a.boundary === 'government'
        ? 'With the government alone in scope, what funds it decides how much of the activity is new to the region.'
        : undefined,
    );
  }
  if (!enterprisesInScope && !governmentInScope) {
    add('financials', 'begin', 'Whatever the boundary turns out to be, this is the record that anchors it.');
    add('payroll', 'begin');
  }

  // Locations. Always needed, and the reason changes with the answer.
  add(
    'locations',
    'begin',
    a.where === 'multi_state'
      ? 'With activity in more than one state, this is what decides which state the first analysis covers.'
      : a.where === 'multi_site_one_state'
        ? 'Several locations in one state means the county detail matters to the result.'
        : undefined,
  );

  if (a.boundary === 'several_enterprises' || a.boundary === 'government_and_enterprises') {
    add('entity_list', 'begin');
    add(
      'intercompany',
      a.intercompany === 'yes' ? 'begin' : 'refine',
      a.intercompany === 'yes'
        ? 'You have said the entities transact with each other, so this is needed before their figures are combined.'
        : undefined,
    );
  }
  if (governmentInScope) {
    add('distributions', 'refine');
  }
  if (has(a.activities, 'federal_contracting')) {
    add(
      'awards',
      a.contracting_place === 'elsewhere' || a.contracting_place === 'mixed' ? 'begin' : 'refine',
      a.contracting_place === 'elsewhere' || a.contracting_place === 'mixed'
        ? 'Work performed outside the region belongs to the place it happens, so place of performance is needed at the start.'
        : undefined,
    );
  }
  if (has(a.activities, 'construction') || has(a.available, 'capital') || a.boundary === 'one_project') {
    add('capital', a.boundary === 'one_project' ? 'begin' : 'refine');
  }
  add('vendor_listing', 'later');
  add('prior_years', 'later');
  add('context', 'later');

  const seen = new Set();
  return picks
    .filter((p) => (seen.has(p.id) ? false : seen.add(p.id)))
    .map((p) => {
      const record = RECORDS[p.id];
      /* A record the person has already said they can reach is not another
         thing to chase. It is shown as in hand, on the same list, so the
         list reads as progress rather than as a demand. */
      const have = (record.satisfiedBy || []).some((v) => has(a.available, v));
      return { ...p, ...record, why: p.why || record.why, have };
    });
}

/**
 * The one thing to do next, chosen from what is already in hand rather
 * than from what is missing. A first file review needs one document, not
 * the whole checklist, and saying so is the difference between a plan
 * somebody starts this week and a plan somebody files.
 */
export function readNextAction(_answers, checklist) {
  const inHand = checklist.filter((r) => r.have);
  const money = inHand.find((r) => r.id === 'financials' || r.id === 'gov_financials');

  if (money) {
    return {
      title: `Send us the ${money.what.toLowerCase()}.`,
      detail:
        'One document is enough to start. An economist reads it and tells you what it supports for the scope above, and which of the gaps below actually matter for your question.',
      caveat: 'A first read is a review, not a confirmation that the analysis can run on it.',
    };
  }
  if (inHand.length > 0) {
    return {
      title: `Send us the ${inHand[0].what.toLowerCase()}.`,
      detail:
        'It is not the whole list, and it does not need to be. An economist reads what you have and says what it supports and what it does not.',
      caveat: 'A first read is a review, not a confirmation that the analysis can run on it.',
    };
  }
  return {
    title: 'Arrange an onboarding call.',
    detail:
      'Nothing has to be gathered first. The call works out which records exist, who holds them and which of them your question actually needs.',
    caveat: '',
  };
}

/** Who needs to help, derived from the unresolved questions rather than from rank. */
export function readParticipants(a) {
  const people = [
    { role: 'Someone who can pull the financial statements', why: 'Every figure starts here.' },
    { role: 'Someone who can pull payroll and headcount', why: 'Labor income and jobs.' },
    {
      role: 'Someone who can approve sharing records outside the organization',
      why: 'Worth naming early. It is the step that most often adds weeks later.',
    },
  ];
  if (a.boundary === 'several_enterprises' || a.boundary === 'government_and_enterprises') {
    people.push({
      role: 'Someone who can say which entities are in scope',
      why: 'The boundary is a decision, not a lookup.',
    });
  }
  if (a.records_held === 'separate' || a.records_held === 'mixed' || a.records_held === 'not_sure') {
    people.push({
      role: 'A coordinator who knows which office holds what',
      why: 'Records held separately need one person tracking who has been asked.',
    });
  }
  if (has(a.activities, 'federal_contracting')) {
    people.push({
      role: 'A contracts or grants administrator',
      why: 'Place of performance and subcontracting live in their records.',
    });
  }
  if (a.boundary === 'government' || a.boundary === 'government_and_enterprises') {
    people.push({
      role: 'The treasurer, finance director or comptroller',
      why: 'Government spending and what funds it.',
    });
  }
  if (has(a.audience, 'funder') || has(a.audience, 'public')) {
    people.push({
      role: 'Whoever will present the result',
      why: 'They should hear the assumptions before they have to defend them.',
    });
  }
  return people;
}

/** Questions the onboarding call should settle, drawn from the answers given. */
export function readOpenQuestions(a) {
  const q = [];
  if (a.goal === 'not_sure' || has(a.audience, 'not_sure'))
    q.push('What the first analysis is for, and who reads it.');
  if (a.boundary === 'not_sure') q.push('What the first analysis covers.');
  if (a.where === 'not_sure') q.push('Which region the results are reported for.');
  if (a.where === 'multi_state')
    q.push('Which state the first analysis covers, and the order the others follow in.');
  if (a.multi_state_anchor === 'spread')
    q.push('Whether to start with the largest state or the one with the best records.');
  if (a.gaming_related_ops === 'not_sure')
    q.push('Whether lodging, food service and retail belong in the first analysis or a later one.');
  if (a.gaming_separable === 'combined' || a.gaming_separable === 'not_sure')
    q.push('How to report gaming and related operations when the figures arrive combined.');
  if (a.contracting_place === 'mixed' || a.contracting_place === 'not_sure')
    q.push('How work performed outside the region is separated from work performed inside it.');
  if (a.contracting_subs === 'yes' || a.contracting_subs === 'not_sure')
    q.push('How much contract value passes through to subcontractors.');
  if (a.contracting_mixed_revenue === 'yes' || a.contracting_mixed_revenue === 'not_sure')
    q.push('How a revenue line covering several kinds of work is split between them.');
  if (a.intercompany === 'yes' || a.intercompany === 'not_sure')
    q.push('Which transactions between the entities have to be removed before the figures are combined.');
  if (a.boundary === 'government_and_enterprises')
    q.push('How transfers between the enterprises and the government are treated.');
  if (a.records_held === 'not_sure' || has(a.available, 'none_yet'))
    q.push('Who holds the records, and who approves sharing them.');
  if (has(a.activities, 'not_sure'))
    q.push('Which activities the first analysis covers.');
  return q;
}

/**
 * Whether the answers support a plan at all. When they do not, the
 * recommendation is a conversation, not a precise plan assembled from
 * assumptions.
 */
export function readConfidence(a) {
  const unsure =
    [a.goal, a.boundary, a.where, a.records_held].filter((v) => v === 'not_sure').length +
    (has(a.audience, 'not_sure') ? 1 : 0);
  const noActivities = has(a.activities, 'not_sure') || (a.activities || []).length === 0;
  const noRecords = has(a.available, 'none_yet') || (a.available || []).length === 0;

  const blocking = [];
  if (a.boundary === 'not_sure') blocking.push('what is being analyzed');
  if (a.goal === 'not_sure') blocking.push('what you want to understand');

  if (blocking.length > 0 || unsure >= 3) {
    return {
      sufficient: false,
      reason:
        blocking.length > 0
          ? `Start with a scoping conversation. Without ${blocking.join(' and ')}, any plan below would be assembled from assumptions rather than from your answers.`
          : 'Start with a scoping conversation. Too much is still open for a plan to be more than a guess.',
    };
  }
  if (noActivities || noRecords) {
    return {
      sufficient: true,
      caveat:
        noRecords
          ? 'The records below are the ones this scope needs. Which of them you can reach is the first thing the call establishes.'
          : 'Naming the activities will sharpen this. The records below hold either way.',
    };
  }
  return { sufficient: true };
}

/** Everything the result panel, the printed checklist and the call outline read. */
export function derivePlan(answers) {
  const a = answers || {};
  const checklist = readChecklist(a);
  return {
    confidence: readConfidence(a),
    scope: readScope(a),
    structure: readStructure(a),
    records: readRecords(a),
    firstOutput: readFirstOutput(a),
    checklist,
    nextAction: readNextAction(a, checklist),
    participants: readParticipants(a),
    openQuestions: readOpenQuestions(a),
  };
}

